class Solution {
public:
    int maximumDetonation(vector<vector<int>>& bombs) {
        int n = bombs.size();
        int best = 0;
        for (int i = 0; i < n; i++) {
            vector<bool> visited(n, false);
            vector<int> stk;
            stk.push_back(i);
            visited[i] = true;
            int count = 0;
            while (!stk.empty()) {
                int cur = stk.back();
                stk.pop_back();
                count++;
                long long cx = bombs[cur][0], cy = bombs[cur][1], cr = bombs[cur][2];
                long long cr2 = cr * cr;
                for (int j = 0; j < n; j++) {
                    if (!visited[j]) {
                        long long dx = (long long)bombs[j][0] - cx;
                        long long dy = (long long)bombs[j][1] - cy;
                        if (dx * dx + dy * dy <= cr2) {
                            visited[j] = true;
                            stk.push_back(j);
                        }
                    }
                }
            }
            best = max(best, count);
        }
        return best;
    }
};
